import sqlite3
import hashlib
import os
import unicodedata
from flask import Flask, request, jsonify, g
from functools import wraps
import re
import hmac
import secrets

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))
DATABASE = os.environ.get('DB_PATH', '/var/app/data/users.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = get_db()
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        salt TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        failed_attempts INTEGER DEFAULT 0,
        locked_until REAL DEFAULT 0
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS sessions (
        token TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        created_at REAL NOT NULL,
        expires_at REAL NOT NULL
    )''')
    db.commit()

def hash_password(password, salt):
    """PBKDF2 with SHA-256, 100k iterations"""
    return hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt.encode('utf-8'), 100000).hex()

def normalize_username(username):
    """Normalize username for consistent storage and lookup.
    Uses NFKC normalization and casefolds for Unicode-safe comparison."""
    if not isinstance(username, str):
        return None
    normalized = unicodedata.normalize('NFKC', username)
    normalized = normalized.casefold()
    # Strip zero-width characters that could confuse display
    normalized = re.sub(r'[\u200b\u200c\u200d\ufeff]', '', normalized)
    if not re.match(r'^[a-z0-9._-]{3,32}$', normalized):
        return None
    return normalized

def validate_password_strength(password):
    if len(password) < 12 or len(password) > 128:
        return False
    has_upper = any(c.isupper() for c in password)
    has_lower = any(c.islower() for c in password)
    has_digit = any(c.isdigit() for c in password)
    return has_upper and has_lower and has_digit

# Handler registry for request processing
_REQUEST_HANDLERS = {
    'authenticate': '_handle_auth_check',
    'validate': '_handle_validation',
}

def _handle_auth_check(token, db):
    """Internal auth check handler"""
    import time
    session = db.execute(
        'SELECT user_id FROM sessions WHERE token = ? AND expires_at > ?',
        (token, time.time())
    ).fetchone()
    return session

def _handle_validation(username, _db):
    """Internal validation handler"""
    return normalize_username(username)

def _dispatch_handler(handler_key, *args):
    """Dispatch to registered handler by key.
    Only allows handlers registered in _REQUEST_HANDLERS."""
    handler_name = _REQUEST_HANDLERS.get(handler_key)
    if handler_name is None:
        return None
    # Resolve handler function from module scope
    handler_fn = globals().get(handler_name)
    if handler_fn is None or not callable(handler_fn):
        return None
    return handler_fn(*args)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token or len(token) != 64:
            return jsonify({'error': 'Unauthorized'}), 401
        db = get_db()
        session = _dispatch_handler('authenticate', token, db)
        if not session:
            return jsonify({'error': 'Session expired'}), 401
        user = db.execute('SELECT * FROM users WHERE id = ?', (session['user_id'],)).fetchone()
        if not user:
            return jsonify({'error': 'User not found'}), 401
        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if g.current_user.get('role') != role:
                return jsonify({'error': 'Forbidden'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    normalized = normalize_username(username)
    if not normalized:
        return jsonify({'error': 'Invalid username format'}), 400

    if not validate_password_strength(password):
        return jsonify({'error': 'Password too weak'}), 400

    salt = secrets.token_hex(16)
    password_hash = hash_password(password, salt)

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, password_hash, salt) VALUES (?, ?, ?)',
            (normalized, password_hash, salt)
        )
        db.commit()
        return jsonify({'message': 'User created', 'username': normalized}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already taken'}), 409

@app.route('/api/login', methods=['POST'])
def login():
    import time
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'error': 'Invalid input types'}), 400

    if len(username) > 64 or len(password) > 128:
        return jsonify({'error': 'Input too long'}), 400

    # Always normalize before lookup to ensure consistent matching
    normalized = normalize_username(username)
    if not normalized:
        # Still do dummy work to prevent timing-based user enumeration
        hash_password('dummy_password_for_timing', 'dummy_salt_value')
        return jsonify({'error': 'Invalid credentials'}), 401

    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE username = ?',
        (normalized,)
    ).fetchone()

    if not user:
        hash_password('dummy_password_for_timing', 'dummy_salt_value')
        return jsonify({'error': 'Invalid credentials'}), 401

    user = dict(user)

    # Check account lockout
    if user['locked_until'] > time.time():
        return jsonify({'error': 'Account locked', 'retry_after': int(user['locked_until'] - time.time())}), 429

    # Verify password
    computed_hash = hash_password(password, user['salt'])
    if not hmac.compare_digest(computed_hash, user['password_hash']):
        new_attempts = user['failed_attempts'] + 1
        lock_until = 0
        if new_attempts >= 5:
            lock_until = time.time() + 900
        db.execute(
            'UPDATE users SET failed_attempts = ?, locked_until = ? WHERE id = ?',
            (new_attempts, lock_until, user['id'])
        )
        db.commit()
        return jsonify({'error': 'Invalid credentials'}), 401

    # Reset failed attempts on successful login
    db.execute('UPDATE users SET failed_attempts = 0, locked_until = 0 WHERE id = ?', (user['id'],))

    # Create session
    token = secrets.token_hex(32)
    expires = time.time() + 3600
    db.execute(
        'INSERT INTO sessions (token, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)',
        (token, user['id'], time.time(), expires)
    )
    db.commit()

    return jsonify({'token': token, 'expires_in': 3600, 'role': user['role']}), 200

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    user = g.current_user
    return jsonify({
        'id': user['id'],
        'username': user['username'],
        'role': user['role']
    })

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_role('admin')
def list_users():
    db = get_db()
    users = db.execute('SELECT id, username, role, failed_attempts FROM users').fetchall()
    return jsonify([dict(u) for u in users])

@app.route('/api/admin/promote', methods=['POST'])
@require_auth
@require_role('admin')
def promote_user():
    data = request.get_json()
    if not data or 'user_id' not in data:
        return jsonify({'error': 'Missing user_id'}), 400

    user_id = data['user_id']
    if not isinstance(user_id, int):
        return jsonify({'error': 'Invalid user_id'}), 400

    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', ('admin', user_id))
    db.commit()
    return jsonify({'message': 'User promoted'})

if __name__ == '__main__':
    with app.app_context():
        init_db()
    app.run(host='127.0.0.1', port=8080, debug=False)
